import {money,state} from './data.js';
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bed:'M3 18v3m18-3v3M3 18h18v-7H3Zm2-7V5h14v6M12 5v6',area:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6M8 16l8-8',car:'m5 6-2 8v5h3v-3h12v3h3v-5l-2-8ZM3 12h18M7 14h1m8 0h1',calendar:'M4 5h16v16H4ZM8 2v6m8-6v6M4 11h16',home:'m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10',layers:'m12 3 10 6-10 6L2 9Zm-10 11 10 6 10-6',bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',filter:'M4 7h16M4 17h16M8 4v6m8 4v6',close:'m5 5 14 14M5 19 19 5',check:'m4 12 5 5L20 6',save:'M5 3h14v19l-7-5-7 5Z',user:'M20 21v-3a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v3M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',building:'M3 21V7h8v14m0-18h10v18M6 10h2m-2 4h2m-2 4h2m6-11h3m-3 4h3m-3 4h3M1 21h22',file:'M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h8',chart:'M4 21V11h3v10m4 0V3h3v18m4 0v-7h3v7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10M10 22h4',plus:'M12 4v16M4 12h16',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sound:'m11 4-6 5H2v6h3l6 5Zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14',train:'M5 3h14v15H5ZM8 21l2-3m4 0 2 3M5 11h14M9 6v5m6 3h1m-8 0h1',download:'M12 3v12m-5-5 5 5 5-5M4 17v5h16v-5',menu:'M3 6h18M3 12h18M3 18h18',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',play:'m8 4 13 8-13 8Z',chevron:'m6 9 6 6 6-6',image:'M3 3h18v18H3Zm0 14 6-6 6 6 3-3 3 3M16 7h.01'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;
export const logo=()=>`<a class="brand" href="#/"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><span>Property<br>Match<span class="brand-dot">.</span></span></a>`;
export const button=(label,href,cls='dark',ic='arrow')=>`<a class="btn ${cls}" href="${href}">${label}${icon(ic)}</a>`;
export const photo=(key,cls='',label='Fotografia ilustrativa de arquitetura')=>`<div role="img" aria-label="${label}" class="photo photo-${key} ${cls}"></div>`;
export const specs=p=>`<div class="specs"><span>${icon('bed')}${p.beds} dorms.</span><span>${icon('area')}${p.area} m²</span><span>${icon('car')}${p.parking} vaga${p.parking!==1?'s':''}</span></div>`;
export const price=p=>`${money(p.price)}${p.mode==='Alugar'?'<small>/mês</small>':''}`;
export function card(p,compact=false){return `<article class="property-card ${compact?'horizontal':''}" data-property="${p.id}"><a class="photo-link" href="#/imovel/${p.id}">${photo(p.photo,'',p.name+' — fotografia ilustrativa')}<span class="pill photo-label">${p.mode==='Alugar'?'Aluguel':'Venda'}</span></a><button class="favorite ${state.favorites.includes(p.id)?'active':''}" data-favorite="${p.id}" aria-label="Salvar ${p.name}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button><div class="card-body"><span class="eyebrow">${p.region} · ${p.id}</span><a href="#/imovel/${p.id}"><h3>${p.name}</h3></a><strong class="price">${price(p)}</strong>${specs(p)}<div class="card-bottom"><span>${icon('pin')}Zona Leste, SP</span><a href="#/imovel/${p.id}" aria-label="Ver ${p.name}">${icon('arrow')}</a></div></div></article>`;}
export function header(active=''){return `<header class="site-header">${logo()}<div class="brand-caption">IMOBILIÁRIA<br>ZONA LESTE · SP</div><nav aria-label="Navegação principal"><a href="#/busca?mode=Comprar" ${active==='comprar'?'class="selected"':''}>Comprar</a><a href="#/busca?mode=Alugar">Alugar</a><a href="#/busca" ${active==='busca'?'class="selected"':''}>Explorar mapa</a><a href="#/match" ${active==='match'?'class="selected"':''}>Property Match<span class="notification-dot"></span></a><a href="#/admin">Para corretores</a></nav><a class="header-saved" href="#/favoritos" aria-label="Favoritos">${icon('save')}</a>${button('Acessar painel','#/admin','dark','user')}<button class="menu-toggle" aria-label="Abrir menu" data-action="menu">${icon('menu')}</button></header>`;}
export const footer=()=>`<footer><div>${logo()}<p>Seu próximo capítulo começa<br>na Zona Leste.</p></div><div><span class="eyebrow">EXPLORE</span><a href="#/busca">Encontre seu imóvel</a><a href="#/match">Property Match</a><a href="#/favoritos">Seus favoritos</a></div><div><span class="eyebrow">PROFISSIONAIS</span><a href="#/admin">Painel administrativo</a><a href="#/admin/documentos">Central de documentos</a><a href="#/design-system">Design system</a></div><div class="footer-note"><span class="demo-label">PROTÓTIPO DEMONSTRATIVO</span><p>Imóveis, valores e avaliações fictícios.<br>Fotografias ilustrativas das referências fornecidas.<br>Nenhuma oferta ou atendimento real.</p><span>São Paulo, Zona Leste · 2026</span></div></footer>`;
export const empty=(title,text,link='#/busca',label='Explorar imóveis')=>`<div class="empty">${icon('search')}<h2>${title}</h2><p>${text}</p>${button(label,link)}</div>`;
export const regionOptions=(selected='')=>`<option value="">Toda a Zona Leste</option>${['Penha','Vila Matilde','Vila Formosa','Tatuapé','Vila Ré','Ponte Rasa','São Miguel Paulista'].map(n=>`<option ${n===selected?'selected':''}>${n}</option>`).join('')}`;
export function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
export function openModal(content){const el=document.querySelector('#modal');el.innerHTML=`<button class="modal-close round" aria-label="Fechar janela" data-action="close-modal">${icon('close')}</button>${content}`;el.showModal();}
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
